(()=>{
'use strict';
const $=s=>document.querySelector(s),main=$('#main'),overlay=$('#overlay'),KEY='sangarsazan.save.v1';
let engine=null,screen='home',order=[],hintCount=0,sound=false,audio=null,timer=null,saveOk=true,pendingImport=null;
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const digits=x=>String(x).replace(/\d/g,d=>'۰۱۲۳۴۵۶۷۸۹'[d]);
function readSave(){try{return localStorage.getItem(KEY)}catch{return null}}
function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';clearTimeout(timer);timer=setTimeout(()=>$('#toast').style.display='none',3500)}
function save(){if(!engine)return;try{localStorage.setItem(KEY,engine.export());saveOk=true}catch{saveOk=false;toast('ذخیره خودکار در این مرورگر ممکن نیست. از فهرست، خروجی ذخیره بگیر.')}}
function scene(id){$('#landscape').innerHTML=GameArt.scenes[id]||GameArt.scenes.marsh}
function modal(title,html,wide=false){overlay.classList.toggle('art-modal',wide);$('#modalTitle').textContent=title;$('#modalBody').innerHTML=html;if(!overlay.open)overlay.showModal()}
function close(){overlay.close()}
function home(){screen='home';scene('marsh');main.innerHTML=`<section class="home"><div class="home-copy"><div class="eyebrow">فصل اول · خیبر</div><h1>راهی<br>میان <em>آب</em></h1><p class="intro">اینجا قهرمان، راهی می‌سازد که دیگران از آن بگذرند.<br>در نقش یک جهادگر جوان، نشانه‌ها را بخوان، تصمیم بگیر و کنار گروهت بمان.</p><div class="home-buttons">${readSave()?'<button class="primary" data-action="continue">ادامه مأموریت ←</button><button data-action="new">شروع دوباره</button>':'<button class="primary" data-action="new">شروع مأموریت ←</button>'}<button class="quiet" data-action="chapters">عملیات‌ها</button></div><div class="chapter-tag">یک مأموریت کوتاه برای تجربه هسته بازی<br>گفت‌وگو · کشف نشانه · انتخاب · ساختن</div></div><div class="scene-caption"><b>هور؛ سکوتی پیش از حرکت</b>برداشتی تصویری از فضای عملیات خیبر<br>محمد؛ جهادگر جوانی در نخستین مأموریتش</div></section>`}
function newGame(){engine=new StoryEngine.Engine(CHAPTERS[0]);order=[];hintCount=0;screen='game';save();render()}
function requestNew(){if(readSave())modal('شروع دوباره',`<p>پیشرفت مأموریت فعلی جایگزین می‌شود. می‌توانی قبل از شروع، از فهرست خروجی ذخیره بگیری.</p><button class="primary" data-action="confirmNew">شروع مأموریت تازه</button><button data-action="close">بازگشت</button>`);else newGame()}
function continueGame(){try{engine=new StoryEngine.Engine(CHAPTERS[0],readSave());screen='game';order=[];render()}catch{modal('ذخیره خوانده نشد','<p>ذخیره قبلی قابل استفاده نیست. می‌توانی فایل ذخیره دیگری وارد کنی یا مأموریت تازه‌ای شروع کنی.</p><button data-action="import">ورود ذخیره</button><button data-action="confirmNew">شروع تازه</button>')}}
function tools(){return `<div class="tools"><button data-action="journal">دفتر <span>${digits(engine.state.journal.length)}</span></button><button data-action="map">نقشه</button><button data-action="gallery">تصاویر</button><button data-action="hint">راهنما</button></div>`}
function comicView(n){const i=engine.comicPanel(),p=n.panels[i];return '<section class="comic-reader"><div class="comic-heading"><div><div class="panel-kicker">روایت تصویری</div><h2>'+esc(n.title)+'</h2></div><button data-action="comicPage">صفحه کامل ⤢</button></div><div class="comic-layout"><figure class="comic-spread"><img class="comic-page-image" src="'+GameArt.assets.comic+'" alt="صفحه کمیک شش‌قابی محمد و مهندس پورشریفی، از جلسه کارگاه تا ساحل هور"><div class="comic-mobile-frame">'+GameArt.frame(p.frame,'قاب '+digits(i+1))+'</div></figure><aside class="comic-reading" aria-live="polite"><div class="panel-kicker">قاب '+digits(i+1)+' از '+digits(n.panels.length)+'</div><div class="comic-progress" aria-label="پیشرفت صفحه">'+n.panels.map((_,j)=>'<span class="'+(j===i?'active':'')+'">'+digits(j+1)+'</span>').join('')+'</div><h3>'+esc(p.speaker)+'</h3><p>'+esc(p.text)+'</p><div class="comic-controls"><button class="primary" data-action="advanceComic">'+(i===n.panels.length-1?'بررسی مدارک ←':'قاب بعد ←')+'</button><button data-action="previousComic" '+(i===0?'disabled':'')+'>قاب قبل</button></div><p class="save-status">قاب فعلی هم همراه پیشرفت بازی ذخیره می‌شود.</p><p class="notice">دیالوگ‌ها بازآفرینی داستانی‌اند؛ چهره مهندس بر پایه عکس آرشیوی طراحی شده است.</p></aside></div></section>'}
function comicPage(){modal('صفحه کامل کمیک','<img class="gallery-image" src="'+GameArt.assets.comic+'" alt="صفحه کامل کمیک شش‌قابی"><p class="notice">برای خواندن متن، به نمایش قاب‌به‌قاب برگرد.</p>',true)}
function gallery(){modal('چهره‌ها و روایت تصویری','<p>محمد، جهادگر جوان خیالی، و مهندس پورشریفی با طراحی برگرفته از عکس آرشیوی. نشان جهاد سازندگی روی سینه هر دو قرار دارد.</p><img class="gallery-image" src="'+GameArt.assets.characters+'" alt="محمد در چپ و مهندس پورشریفی در راست، با نشان جهاد سازندگی روی سینه"><h3>ساحل هور در شب</h3><img class="gallery-image gallery-night" src="'+GameArt.assets.night+'" alt="تصویر شبانه کارگاه و پل شناور، ارسالی متین"><button class="primary" data-action="comicPage">دیدن صفحه کامل کمیک</button>',true)}
function render(){const n=engine.current();screen='game';scene(n.scene);const top=`<div class="game-top"><div><div class="chapter-title">${CHAPTERS[0].subtitle} / ${CHAPTERS[0].title}</div><div class="objective">◇ ${esc(n.objective||'گفت‌وگو را دنبال کن')}</div></div>${tools()}</div>`;let content='';
if(n.type==='comic'){content=comicView(n)}
else if(n.type==='inspect'){content=`<section class="content-panel"><div class="panel-kicker">بررسی مدارک</div><h2>${n.title}</h2><p class="panel-copy">${n.text}</p><div class="evidence-grid">${n.items.map(i=>`<button class="evidence" data-inspect="${i.id}"><span class="icon">${i.icon}</span><span>${i.title}</span><span class="read-label">${engine.state.flags[i.id]?'✓ خوانده شد':'برای بررسی باز کن'}</span></button>`).join('')}</div><div class="panel-actions"><span class="hint">${digits(n.required.filter(x=>engine.state.flags[x]).length)} از ${digits(n.required.length)} مدرک بررسی شده</span><button class="primary" data-action="finishInspect" ${n.required.every(x=>engine.state.flags[x])?'':'disabled'}>برگشت به گفت‌وگو ←</button></div></section>`}
else if(n.type==='puzzle'){content=`<section class="content-panel"><div class="panel-kicker">میز کار گروه</div><h2>${n.title}</h2><p class="panel-copy">${n.text}</p><div class="slots">${[0,1,2,3].map((_,i)=>`<div class="slot ${order[i]?'filled':''}"><span>گام ${digits(i+1)}</span>${order[i]?n.items.find(x=>x.id===order[i]).label:'کارت را انتخاب کن'}</div>`).join('')}</div><div class="puzzle-bank">${n.items.map(i=>`<button data-card="${i.id}" ${order.includes(i.id)?'disabled':''}>${i.label}</button>`).join('')}</div><div class="panel-actions"><button class="primary" data-action="checkPuzzle" ${order.length===4?'':'disabled'}>بررسی ترتیب</button><button data-action="resetPuzzle">چیدن دوباره</button><span id="puzzleFeedback" class="hint" role="status"></span></div><p class="notice">این فعالیت، معمای داستانی است و آموزش فنی ساخت پل نیست.</p></section>`}
else if(n.type==='ending'){content=`<section class="ending"><div class="end-seal">◇</div><div class="panel-kicker">مأموریت نمونه به پایان رسید</div><h2>${n.title}</h2><p>${n.text}</p><h3>${n.outcome}</h3><div class="stats"><div><strong>${digits(engine.state.stats.care)}</strong>تصمیم همراه با دقت</div><div><strong>${digits(engine.state.journal.length)}</strong>یادداشت ثبت‌شده</div><div><strong>${digits(engine.state.visited.length)}</strong>صحنه تجربه‌شده</div></div><p class="notice">انتخاب‌های شما روند همین مأموریت خیالی را تغییر دادند؛ نتیجه تاریخی عملیات تغییر نمی‌کند.</p><button class="primary" data-action="journal">مرور دفتر مأموریت</button><button data-action="new">تجربه مسیر دیگر</button><button class="quiet" data-action="home">صفحه اصلی</button></section>`}
else{content=`<div class="stage">${GameArt.portrait(n.portrait)?`<div class="portrait ${n.side||'right'}" role="img" aria-label="تصویر کمیک ${esc(n.speaker)}">${GameArt.portrait(n.portrait)}</div>`:''}<div class="location-label">${{marsh:'ساحل هور',workshop:'کارگاه مهندسی',tent:'چادر مأموریت',bridge:'مسیر آزمایشی',dawn:'نزدیک روشنایی'}[n.scene]||''}</div></div><section class="dialogue" aria-live="polite"><div class="speaker">${esc(n.speaker)}</div><p>${esc(n.text)}</p>${n.type==='choice'?`<div class="choice-list">${engine.available().map(c=>`<button data-choice="${c.id}">${esc(c.label)}</button>`).join('')}</div>`:''}<div class="dialogue-bottom"><span class="save-status">${saveOk?'پیشرفت در این مرورگر ذخیره می‌شود':'ذخیره خودکار در دسترس نیست'} · ${digits(engine.state.visited.length)} صحنه</span>${n.type!=='choice'?'<button class="primary next" data-action="next">ادامه ←</button>':'<span class="save-status">یک پاسخ را انتخاب کن</span>'}</div></section>`}
main.innerHTML=`<section class="game">${top}${content}</section>`;window.scrollTo({top:0,behavior:'instant'});
}
function journal(){if(!engine){modal('دفتر مأموریت','<p>پس از شروع بازی، سرنخ‌ها و گزارش تصمیم‌ها اینجا ثبت می‌شوند.</p>');return}modal('دفتر مأموریت',engine.state.journal.length?engine.state.journal.map(i=>`<article class="journal-entry"><h3>${esc(i.title)}</h3><p>${esc(i.text)}</p></article>`).join(''):'<p>هنوز یادداشتی ثبت نشده. اولین مدرک را که پیدا کنی، اینجا می‌ماند.</p>')}
function map(){modal('طرح شماتیک مأموریت',`<svg class="map-svg" viewBox="0 0 600 320" role="img" aria-label="نقشه شماتیک کارگاه، ساحل و مسیر آزمایش"><rect width="600" height="320" rx="8" fill="#afb498"/><path d="M0 150Q100 100 210 170T600 170V320H0Z" fill="#718f87"/><g stroke="#455d4e" fill="none" stroke-dasharray="7 7" stroke-width="3"><path d="M100 95L280 155 470 240"/></g><g font-family="Tahoma" font-size="17" text-anchor="middle" fill="#263e34">${[{x:100,y:95,id:'workshop',t:'کارگاه'},{x:280,y:155,id:'shore',t:'ساحل'},{x:470,y:240,id:'test',t:'محل آزمایش'}].map(i=>`<g class="map-location" data-map="${i.id}" role="button" tabindex="0" aria-label="${i.t}"><circle cx="${i.x}" cy="${i.y}" r="16" fill="#dccc9c" stroke="#415b4e" stroke-width="3"/><text x="${i.x}" y="${i.y-30}">${i.t}</text></g>`).join('')}</g></svg><p id="mapInfo" class="map-note">روی هر نقطه بزن تا توضیحش را بخوانی.</p><p class="notice">این تصویر نقشه جغرافیایی یا نظامی واقعی نیست. فقط ارتباط مکان‌های داستان را نشان می‌دهد.</p>`)}
function hint(){if(!engine){toast('اول مأموریت را شروع کن.');return}const n=engine.current();let t=n.type==='comic'?'با دکمه قاب بعد، صفحه را بخوان. روی گوشی، هر قاب جدا و بزرگ نشان داده می‌شود. دکمه صفحه کامل هر شش قاب را کنار هم باز می‌کند.':n.type==='inspect'?'هر سه کارت روی میز را باز کن؛ بعد دکمه برگشت به گفت‌وگو فعال می‌شود.':n.type==='puzzle'?(hintCount++?'ترتیب: بازدید اولیه، آماده‌سازی قطعه، اتصال قطعه، بازبینی نهایی.':'یادداشت یونس را بخوان. پیش از دست‌زدن به قطعه چه می‌کنی؟ پس از اتصال چه چیزی باقی می‌ماند؟'):n.type==='choice'?'می‌توانی به دفتر برگردی و نشانه‌ها را مرور کنی. انتخاب اشتباه بن‌بست ایجاد نمی‌کند، اما روی روند مأموریت اثر می‌گذارد.':n.type==='ending'?'می‌توانی دفتر را مرور کنی یا برای تجربه انتخاب‌های دیگر از نو شروع کنی.':'دکمه ادامه را بزن. دفتر و نقشه در طول گفت‌وگو در دسترس هستند.';modal('راهنمای این بخش',`<p>${t}</p>`)}
function chapters(){modal('عملیات‌ها',`<div class="chapter-card"><span class="panel-kicker">قابل بازی</span><h3>خیبر · راهی میان آب</h3><p>یک مأموریت نمونه برای آزمایش گفت‌وگو، تصمیم‌ها و فعالیت‌های تعاملی.</p><button class="primary" data-action="${readSave()?'continue':'confirmNew'}">${readSave()?'ادامه مأموریت':'ورود به مأموریت'}</button></div><div class="chapter-card locked"><h3>عملیات بعدی</h3><p>هنوز محتوایی برای این بخش ساخته نشده است.</p></div>`)}
function menu(){modal('فهرست',`<div class="menu-grid">${engine?'<button data-action="resume">بازگشت به بازی</button><button data-action="journal">دفتر مأموریت</button><button data-action="history">مرور گفت‌وگوها</button><button data-action="export">دریافت فایل ذخیره</button>':''}<button data-action="import">ورود فایل ذخیره</button><button data-action="chapters">عملیات‌ها</button><button data-action="gallery">طراحی شخصیت‌ها و تصاویر</button><button data-action="about">درباره این نسخه</button><button data-action="home">صفحه اصلی</button></div>`)}
function exportSave(){if(!engine)return;const blob=new Blob([engine.export()],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='sangarsazan-save.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('فایل ذخیره دریافت شد.')}
function importSave(){const input=document.createElement('input');input.type='file';input.accept='.json,application/json';input.onchange=async()=>{const file=input.files[0];if(!file)return;if(file.size>500000){toast('این فایل بیش از حد بزرگ است.');return}try{const raw=await file.text();new StoryEngine.Engine(CHAPTERS[0],raw);pendingImport=raw;modal('ورود ذخیره',`<p>فایل معتبر است. پیشرفت فعلی با این فایل جایگزین شود؟</p><button class="primary" data-action="confirmImport">بارگذاری ذخیره</button><button data-action="close">بازگشت</button>`)}catch{toast('فایل ذخیره معتبر نیست.')}};input.click()}
async function toggleSound(){try{if(!audio){audio=new(window.AudioContext||window.webkitAudioContext)();const buffer=audio.createBuffer(1,audio.sampleRate*3,audio.sampleRate),data=buffer.getChannelData(0);for(let i=0;i<data.length;i++)data[i]=(Math.random()*2-1)*.12;const noise=audio.createBufferSource();noise.buffer=buffer;noise.loop=true;const filter=audio.createBiquadFilter();filter.type='lowpass';filter.frequency.value=280;const gain=audio.createGain();gain.gain.value=.15;noise.connect(filter).connect(gain).connect(audio.destination);noise.start();await audio.suspend()}sound=!sound;await audio[sound?'resume':'suspend']();$('#sound').textContent=sound?'صدا روشن':'صدا خاموش';$('#sound').setAttribute('aria-pressed',String(sound))}catch{toast('صدای محیط در این مرورگر پشتیبانی نمی‌شود.')}}
const actions={new:requestNew,confirmNew:()=>{close();newGame()},continue:()=>{close();continueGame()},home:()=>{close();home()},next:()=>{engine.next();save();render()},journal,map,hint,chapters,menu,close,gallery,comicPage,advanceComic:()=>{engine.advanceComic();save();render()},previousComic:()=>{engine.previousComic();save();render()},resume:close,export:exportSave,import:importSave,confirmImport:()=>{engine=new StoryEngine.Engine(CHAPTERS[0],pendingImport);pendingImport=null;order=[];save();close();render()},finishInspect:()=>{if(engine.finishInspection()){save();render()}},resetPuzzle:()=>{order=[];render()},checkPuzzle:()=>{if(engine.solve(order)){order=[];save();render()}else{$('#puzzleFeedback').textContent='این ترتیب جور درنمی‌آید. کارت‌ها را دوباره بچین؛ راهنما هم در دسترس است.'}},history:()=>modal('گفت‌وگوهای گذشته',engine.state.history.map(i=>`<div class="history-entry"><span>${esc(i.speaker)}</span><p>${esc(i.text)}</p></div>`).join('')||'<p>هنوز گفت‌وگویی ثبت نشده.</p>'),about:()=>modal('درباره این نسخه','<p>سنگرسازان / جهادگران، هسته بازی روایی دوبعدی با یک مأموریت نمونه از فضای خیبر است. نقش بازیکن و یونس خیالی‌اند. تمام دیالوگ‌های منتسب به مهندس پورشریفی در این نمونه بازآفرینی نویسنده‌اند و نقل‌قول مستند نیستند.</p><p>محمد شخصیتی خیالی است. طراحی چهره پورشریفی بر پایه عکس یادبود آرشیوشده انجام شده و بازآفرینی هنری است. نشان جهاد سازندگی روی سینه هر دو شخصیت قرار دارد. این نسخه هنوز شامل فصل کامل ۲۰ تا ۳۰ دقیقه‌ای، دوبله و بسته اندروید نیست.</p><p>مبنای اولیه: فایل پژوهشی خیبر ارائه‌شده توسط متین. تاریخ‌ها، جزئیات و انتساب‌های ناسازگار آن، پیش از نگارش نسخه نهایی باید با منابع دست‌اول بررسی شوند.</p><p>نسخه ۰.۲ · بدون حساب کاربری · بدون ارسال ذخیره‌ها به سرور</p>')};
document.addEventListener('click',ev=>{const el=ev.target.closest('button,[data-map]');if(!el||el.disabled)return;if(el.dataset.action){actions[el.dataset.action]?.();return}if(el.dataset.choice){engine.choose(el.dataset.choice);save();render();return}if(el.dataset.inspect){const item=engine.inspect(el.dataset.inspect);save();render();modal(item.title,`<p>${esc(item.text)}</p><button class="primary" data-action="close">ثبت شد؛ برگشت به میز</button>`);return}if(el.dataset.card){order.push(el.dataset.card);render();return}if(el.dataset.map){$('#mapInfo').textContent={workshop:'کارگاه: تطبیق برچسب‌ها و هماهنگی با گروه مهندسی.',shore:'ساحل: دریافت گزارش و هماهنگی گروه.',test:'محل آزمایش: فعالیت چهارکارتی و بازبینی نهایی.'}[el.dataset.map]}});
document.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.dataset.map){e.preventDefault();e.target.dispatchEvent(new MouseEvent('click',{bubbles:true}));return}if(overlay.open||['BUTTON','INPUT','A'].includes(e.target.tagName))return;if((e.key===' '||e.key==='Enter')&&screen==='game'){if(engine.current().type==='dialogue'){e.preventDefault();actions.next()}else if(engine.current().type==='comic'){e.preventDefault();actions.advanceComic()}}});
$('#closeModal').onclick=close;$('#menuButton').onclick=menu;$('#brand').onclick=e=>{e.preventDefault();if(screen==='game')menu();else home()};$('#sound').onclick=toggleSound;overlay.addEventListener('click',e=>{if(e.target===overlay){const r=overlay.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)close()}});document.addEventListener('visibilitychange',()=>{if(document.hidden&&audio)audio.suspend();else if(audio&&sound)audio.resume()});
StoryEngine.validate(CHAPTERS[0]);home();
})();
